SELECT Имена_станций.NAME, Имена_ОЭС.nameoes, Имена_областей.NAME AS oblname, [Станции(архив)].numb1, [Станции(архив)].year, [Станции(архив)].nust, [Станции(архив)].E, [Станции(архив)].eotp, [Станции(архив)].eurt, [Станции(архив)].eust, [Станции(архив)].Q, [Станции(архив)].turt, [Станции(архив)].tust, [Станции(архив)].B, [Станции(архив)].gaz, [Доп_угли(архив)].gazpp, [Станции(архив)].mazut, [Станции(архив)].torf, [Станции(архив)].slan, [Станции(архив)].proch, [Станции(архив)].ugol, [Станции(архив)].don, [Станции(архив)].podm, [Станции(архив)].pech, [Доп_угли(архив)].intin, [Доп_угли(архив)].vork, [Станции(архив)].arkt, [Станции(архив)].kuzn, [Станции(архив)].ural, [Доп_угли(архив)].sver, [Доп_угли(архив)].chel, [Доп_угли(архив)].kizel, [Станции(архив)].bashk, [Станции(архив)].kan, [Доп_угли(архив)].nazar, [Доп_угли(архив)].ibor, [Доп_угли(архив)].berez, [Доп_угли(архив)].per, [Станции(архив)].tung, [Доп_угли(архив)].jer, [Доп_угли(архив)].karab, [Станции(архив)].irkut, [Доп_угли(архив)].mug, [Доп_угли(архив)].azey, [Доп_угли(архив)].cher, [Станции(архив)].hak, [Станции(архив)].tuv, [Станции(архив)].bur, [Доп_угли(архив)].gusin, [Доп_угли(архив)].tugn, [Станции(архив)].chit, [Доп_угли(архив)].har, [Доп_угли(архив)].urt, [Доп_угли(архив)].neru, [Доп_угли(архив)].pyak, [Доп_угли(архив)].rai, [Доп_угли(архив)].erk, [Станции(архив)].urg, [Станции(архив)].prim, [Станции(архив)].luch, [Станции(архив)].mag, [Станции(архив)].sah, [Станции(архив)].ushum, [Станции(архив)].qotr, [Станции(архив)].snk, [Станции(архив)].ewtp, [Станции(архив)].NTsum, [Станции(архив)].nt, [Станции(архив)].obor, [Станции(архив)].ved, [Станции(архив)].obl, [Станции(архив)].dep, [Станции(архив)].oes, [Станции(архив)].er, [Станции(архив)].numb1120, Имена_станций.Ведомство AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.BE AS BE, Имена_станций.GK AS GK, IIf([obor]=20 Or [obor]=90,"ГТУ",IIf([obor]=21 Or [obor]=91,"ПГУ",IIf([obor]=22,"Диз",IIf([obor]=23,"Дет","ПСУ")))) AS тип, IIf([be]<>9,имена_ГК!name1,имена_БЕ!name) AS nameGK, IIf([Станции(архив)]!obl=18 Or [Станции(архив)]!be=9,[Москва и МО]!newobl,[Станции(архив)]!obl) AS nobl
FROM (((((([Станции(архив)] INNER JOIN Имена_станций ON [Станции(архив)].numb1120=Имена_станций.NUMB) INNER JOIN Имена_ОЭС ON [Станции(архив)].oes=Имена_ОЭС.oes) INNER JOIN Имена_областей ON [Станции(архив)].obl=Имена_областей.OBL) LEFT JOIN [Доп_угли(архив)] ON ([Станции(архив)].numb1120=[Доп_угли(архив)].NUMB1120) AND ([Станции(архив)].year=[Доп_угли(архив)].YEAR)) LEFT JOIN имена_ГК ON [Станции(архив)].gk=имена_ГК.code) LEFT JOIN имена_БЕ ON [Станции(архив)].be=имена_БЕ.code) INNER JOIN [Москва и МО] ON [Станции(архив)].numb1120=[Москва и МО].NUMB;
